    /// <summary>Gets the alignment of a type: the offset at which a sequential structure places it after one byte.</summary>
    /// <typeparam name="T">The type.</typeparam>
    /// <returns>The alignment, in bytes.</returns>
    private static nuint AlignmentOf<T>()
        where T : unmanaged
    {
        return (nuint)(sizeof(AlignmentProbe<T>) - sizeof(T));
    }

    /// <summary>Describes an entry for a difference.</summary>
    /// <param name="entry">The entry.</param>
